JavaScript:
```javascript
const searchInput = document.getElementById('search-input');
const predictionList = document.getElementById('predictions');

searchInput.addEventListener('input', async (e) => {
  const query = e.target.value;
  const response = await fetch(`https://www.googleapis.com/customsearch/v1?key=YOUR_API_KEY&cx=YOUR_SEARCH_ENGINE_ID&q=${query}`);
  const data = await response.json();
  const predictions = data.items.map((item) => `<li>${item.title}</li>`).join('');
  predictionList.innerHTML = predictions;
});
```
